import Foundation
import Testing
@testable import GraineInApp

/**
 * THE NATIVE CALL ENGINE AGAINST contract/native-calls.json — vectors
 * generated BY the React Native SDK's TypeScript (generate-native-calls.mjs),
 * which iOS and Android must reproduce exactly. Every case, every sample.
 * A missing vectors file FAILS — it never skips.
 */
@Suite struct NativeCallVectorTests {
    private let vectors: OrderedJSON

    init() throws {
        vectors = try NativeVectors.load()
    }

    // MARK: - Agent audio

    @Test func everyMuLawByteDecodesAsTheReferenceDoes() throws {
        let expected = try #require(vectors["mulaw"]?.array).compactMap { $0.int }
        #expect(expected.count == 256)
        #expect(AgentAudio.muLawTable.map { Int($0) } == expected)
        #expect(AgentAudio.decodeMuLaw(Array(0...255)).map { Int($0) } == expected)
    }

    @Test func everyDecodeCaseMatchesToTheSample() throws {
        let cases = try #require(vectors["decode"]?.array)
        #expect(cases.count == 6)
        for c in cases {
            let name = c["name"]?.string ?? "?"
            let encoded = try #require(c["data"]?.string, "\(name): data")
            let bytes = try #require(Data(base64Encoded: encoded).map { [UInt8]($0) }, "\(name): base64")
            let declared = c["declared"]
            let latched: AgentAudioFormat? = try c["latched"].flatMap { l in
                if l.isNull { return nil }
                let kind = try #require(AgentAudioFormat.Kind(rawValue: l["kind"]?.string ?? ""))
                return AgentAudioFormat(kind: kind, sampleRate: try #require(l["sampleRate"]?.int))
            }
            let decoded = try #require(AgentAudio.decode(
                bytes,
                declaredFormat: declared?["format"]?.string,
                declaredRate: declared?["sampleRate"]?.int,
                latched: latched,
                fallbackPcmRate: 24_000
            ), "\(name): decoded")
            let expect = try #require(c["expect"])
            #expect(decoded.kind.rawValue == expect["kind"]?.string, "\(name): kind")
            #expect(decoded.sampleRate == expect["sampleRate"]?.int, "\(name): rate")
            #expect(decoded.pcm16.count == expect["samples"]?.int, "\(name): samples")
            if let latch = expect["latch"], !latch.isNull {
                #expect(decoded.latch?.kind.rawValue == latch["kind"]?.string, "\(name): latch kind")
                #expect(decoded.latch?.sampleRate == latch["sampleRate"]?.int, "\(name): latch rate")
            } else {
                #expect(decoded.latch == nil, "\(name): must not latch")
            }
            let head = try #require(expect["head"]?.array).compactMap { $0.int }
            let tail = try #require(expect["tail"]?.array).compactMap { $0.int }
            #expect(decoded.pcm16.prefix(head.count).map { Int($0) } == head, "\(name): head")
            #expect(decoded.pcm16.suffix(tail.count).map { Int($0) } == tail, "\(name): tail")
        }
    }

    @Test func anEmptyFrameDecodesToNothing() {
        #expect(AgentAudio.decode([], declaredFormat: nil, declaredRate: nil, latched: nil) == nil)
    }

    @Test func anOddTrailingByteIsDroppedNotPlayed() {
        #expect(AgentAudio.decodePcm16([0x01, 0x02, 0x03]) == [0x0201])
    }

    // MARK: - The echo guard

    @Test func everyEchoGuardScenarioReleasesExactlyTheSameFrames() throws {
        let scenarios = try #require(vectors["echoGuard"]?.array)
        #expect(scenarios.count == 3)
        for scenario in scenarios {
            let name = scenario["name"]?.string ?? "?"
            let frameMs = try #require(scenario["frameMs"]?.double)
            var guardian = EchoGuard<String>()
            var id = 0
            for (i, step) in try #require(scenario["steps"]?.array).enumerated() {
                let amp = try #require(step["amp"]?.double)
                let audible = step["audible"].map { if case .bool(let b) = $0 { return b }; return false } ?? false
                let tag = "f\(id)"
                id += 1
                let released = guardian.filter(tag, pcm: NativeAudioFixtures.micSamples(amp: amp), agentAudible: audible, frameMs: frameMs)
                let expected = try #require(step["released"]?.array).compactMap { $0.string }
                #expect(released == expected, "\(name), step \(i)")
            }
        }
    }

    @Test func theGuardFailsOpenWheneverTheAgentIsNotAudible() {
        var guardian = EchoGuard<Int>()
        for i in 0..<20 { _ = guardian.filter(i, pcm: NativeAudioFixtures.micSamples(amp: 1_500), agentAudible: true, frameMs: 20) }
        #expect(guardian.filter(99, pcm: NativeAudioFixtures.micSamples(amp: 50), agentAudible: false, frameMs: 20) == [99])
    }

    // MARK: - Variables

    @Test func everyContextTokenIsTheSameBytes() throws {
        let cases = try #require(vectors["contextToken"]?.array)
        #expect(cases.count == 4)
        for c in cases {
            let name = c["name"]?.string ?? "?"
            let vars = try #require(c["vars"]).orderedPairs
            let callType = c["callType"]?.string ?? "webcall"
            let token = CallWire.contextToken(vars, callType: callType)
            if let expect = c["expect"], !expect.isNull {
                #expect(token == expect.string, "\(name)")
            } else {
                #expect(token == nil, "\(name): no token")
            }
        }
    }

    @Test func everyTicketMetadataCaseKeepsWhatTheServerKeeps() throws {
        let block = try #require(vectors["ticketMetadata"])
        let limits = try #require(block["limits"])
        #expect(limits["keys"]?.int == CallWire.ticketKeyLimit)
        #expect(limits["keyLength"]?.int == CallWire.ticketKeyLength)
        #expect(limits["valueLength"]?.int == CallWire.ticketValueLength)
        #expect(limits["totalBytes"]?.int == CallWire.ticketTotalBytes)
        let cases = try #require(block["cases"]?.array)
        #expect(cases.count == 5)
        for c in cases {
            let name = c["name"]?.string ?? "?"
            let got = CallWire.ticketMetadata(try #require(c["vars"]).orderedPairs)
            if let expect = c["expect"], !expect.isNull {
                let want = try #require(expect.fields).map { ($0.0, $0.1.string ?? "") }
                #expect(got?.map { $0.0 } == want.map { $0.0 }, "\(name): keys, in order")
                #expect(got?.map { $0.1 } == want.map { $0.1 }, "\(name): values")
            } else {
                #expect(got == nil, "\(name): nothing at all")
            }
        }
    }

    // MARK: - Spoken captions

    @Test func spokenPhrasesJoinExactlyAsTheReferenceJoinsThem() throws {
        let cases = try #require(vectors["spokenJoin"]?.array)
        #expect(cases.count == 6)
        for c in cases {
            let chunks = try #require(c["chunks"]?.array).compactMap { $0.string }
            let joined = chunks.reduce("") { soFar, next in soFar + CallWire.spokenJoinGap(soFar, next) + next }
            #expect(joined == c["expect"]?.string, "\(chunks.first ?? "")…")
        }
    }

    // MARK: - Frames and constants

    @Test func theConstantsAreTheContracts() throws {
        let f = try #require(vectors["frames"])
        #expect(f["subprotocol"]?.string == CallWire.subprotocol)
        #expect(f["pingMs"]?.double == CallWire.pingSeconds * 1_000)
        #expect(f["socketOpenTimeoutMs"]?.double == CallWire.socketOpenTimeoutSeconds * 1_000)
        #expect(f["actionDeadlineMs"]?.int == CallWire.actionDeadlineMs)
        #expect(CallWire.actionAnswerMs < CallWire.actionDeadlineMs)
        #expect(f["agentPcmRate"]?.int == AgentAudio.fallbackPcmRate)
        #expect(f["captureRate"]?.int == CallWire.captureRate)
        #expect(CallWire.captureFrameSamples * 1_000 / CallWire.captureRate == 20)
        #expect(f["minPlayoutBufferSeconds"]?.double == PlayoutPolicy.startSeconds)
        #expect(f["drainAfterMs"]?.double == PlayoutPolicy.drainAfterSeconds * 1_000)
        #expect(f["markAckCapMs"]?.double == CallWire.markAckCapSeconds * 1_000)
        #expect(f["agentAudibleRecencyMs"]?.double == AgentSpeech.audibleRecencySeconds * 1_000)
        #expect(f["speakingTailMs"]?.double == AgentSpeech.tailSeconds * 1_000)
    }

    @Test func everyFrameHasTheContractsShape() throws {
        let f = try #require(vectors["frames"])
        func shape(_ key: String, replacing: [String: Any] = [:]) throws -> [String: Any] {
            var o = try #require(f[key]?.foundation as? [String: Any], "\(key)")
            for (k, v) in replacing { o[k] = v }
            return o
        }
        func same(_ text: String, _ expected: [String: Any], _ label: String) {
            #expect(JSON.canonical(JSON.object(from: text)) == JSON.canonical(expected), "\(label): \(text)")
        }

        var initFrame = try shape("init")
        var meta = try #require(initFrame["meta_data"] as? [String: Any])
        meta["client"] = "graine-ios-sdk"
        initFrame["meta_data"] = meta
        same(CallWire.initFrame(variables: [("who_called", "agent")]), initFrame, "init")

        same(CallWire.audioFrame(base64: "AAAA"), try shape("audio", replacing: ["data": "AAAA"]), "audio")
        same(CallWire.bargeInFrame, try shape("bargeIn"), "barge_in")
        same(CallWire.markFrame(name: "m-1"), try shape("markAck", replacing: ["name": "m-1"]), "mark")
        same(CallWire.pingFrame, try shape("ping"), "ping")
        same(CallWire.stopFrame, try shape("stop"), "stop")
        same(
            CallWire.actionResultFrame(actionId: "a-1", result: .refused("no")),
            try shape("actionResult", replacing: ["action_id": "a-1", "status": "refused", "message": "no"]),
            "app_action_result"
        )
        // Nothing to say is said with no key at all.
        same(CallWire.actionResultFrame(actionId: "a-2", result: .ok()), ["type": "app_action_result", "action_id": "a-2", "status": "ok"], "ok, bare")

        let ticket = String(decoding: CallWire.ticketRequest(publishableKey: "<key>", metadata: [("who_called", "agent")]), as: UTF8.self)
        same(ticket, try shape("ticketRequest"), "ticket request")
        let bare = String(decoding: CallWire.ticketRequest(publishableKey: "<key>", metadata: nil), as: UTF8.self)
        #expect(JSON.object(from: bare)?["metadata"] == nil, "no metadata is no key")

        let template = try #require(f["directUrl"]?.string)
        let url = CallWire.directUrl(wsHost: "{wsHost}", agentId: "AGENT")
        #expect(url == template.replacingOccurrences(of: "{agentId}", with: "AGENT"))
    }

    @Test func theFixedFramesAreWrittenByteForByte() {
        #expect(CallWire.stopFrame == #"{"type":"stop","event":"stop","data":"client_hangup"}"#)
        #expect(CallWire.audioFrame(base64: "QUJD") ==
                #"{"type":"audio","data":"QUJD","meta_info":{"format":"pcm","sample_rate":16000,"encoding":"base64"}}"#)
        #expect(CallWire.initFrame(variables: [("who_called", "agent"), ("name", "राहुल")]) ==
                #"{"type":"init","event":"start","meta_data":{"client":"graine-ios-sdk","context_data":{"who_called":"agent","name":"राहुल"}}}"#)
    }
}

/// The wire's smaller rules, beyond the vectors.
@Suite struct CallWireTests {
    @Test func stringsAreEscapedAsJsonStringifyEscapesThem() {
        #expect(WireJSON.string("a\"b\\c/d\n\t\u{01}é\u{2028}").text == "\"a\\\"b\\\\c/d\\n\\t\\u0001é\u{2028}\"")
    }

    @Test func numbersAreWrittenAsJavaScriptWritesThem() {
        #expect(WireJSON.from(1299).text == "1299")
        #expect(WireJSON.from(12.5).text == "12.5")
        #expect(WireJSON.from(25.0).text == "25")
        #expect(WireJSON.from(Double.nan).text == "null")
        #expect(WireJSON.from(true).text == "true")
        #expect(WireJSON.from(["b": 1, "a": [true, NSNull()]] as [String: Any]).text == #"{"a":[true,null],"b":1}"#)
    }

    @Test func theTokenIsAppendedToWhicheverUrlWasChosen() {
        #expect(CallWire.withContextToken("wss://ws.graine.ai/x?webcall=1", token: "a+b/c=") ==
                "wss://ws.graine.ai/x?webcall=1&context_token=a%2Bb%2Fc%3D")
        #expect(CallWire.withContextToken("wss://ws.graine.ai/x", token: "t") == "wss://ws.graine.ai/x?context_token=t")
        #expect(CallWire.withContextToken("wss://ws.graine.ai/x", token: nil) == "wss://ws.graine.ai/x")
    }

    @Test func theDirectUrlDefaultsToGrainesHostAndEncodesTheAgent() {
        #expect(CallWire.directUrl(wsHost: nil, agentId: "a b") == "wss://ws.graine.ai/chat/v1/a%20b?webcall=1")
        #expect(CallWire.directUrl(wsHost: "wss://ws.graine.ai/", agentId: "x") == "wss://ws.graine.ai/chat/v1/x?webcall=1")
    }

    @Test func aTokenKeyIsTrimmedAndAnEmptyOneDropped() throws {
        let token = try #require(CallWire.contextToken([("  name ", "Asha"), ("   ", "x")]))
        let json = String(decoding: try #require(Data(base64Encoded: token)), as: UTF8.self)
        #expect(json == #"{"name":"Asha","call_type":"webcall","recipient_data":{"name":"Asha","call_type":"webcall"}}"#)
    }

    @Test func markersAreRemovedAndNothingElseIsTouched() {
        #expect(CallWire.readAgentChunk("Welcome to Tring ") == .init(text: "Welcome to Tring ", startsTurn: false, endsTurn: false))
        #expect(CallWire.readAgentChunk("<end_of_stream>") == .init(text: "", startsTurn: false, endsTurn: true))
        #expect(CallWire.readAgentChunk("<BEGINNING_OF_STREAM>Hi ") == .init(text: "Hi ", startsTurn: true, endsTurn: false))
        #expect(CallWire.readAgentChunk("bye.<end_of_stream>") == .init(text: "bye.", startsTurn: false, endsTurn: true))
        #expect(CallWire.readAgentChunk("a < b") == .init(text: "a < b", startsTurn: false, endsTurn: false))
    }

    @Test func base64IsReadLeniently() {
        #expect(CallWire.base64Bytes("QUJD") == [65, 66, 67])
        #expect(CallWire.base64Bytes("QUI") == [65, 66])
        #expect(CallWire.base64Bytes("QU\nJD") == [65, 66, 67])
    }

    @Test func inboundFramesAreTyped() throws {
        guard case let .audio(data, format, rate)? = CallInbound.parse(#"{"type":"audio","data":"AAA="}"#) else {
            Issue.record("audio"); return
        }
        #expect(data == "AAA=")
        #expect(format == nil)
        #expect(rate == nil)
        guard case let .audio(_, f2, r2)? = CallInbound.parse(#"{"type":"audio","data":"","meta_info":{"format":"mulaw","sample_rate":"8000"}}"#) else {
            Issue.record("declared audio"); return
        }
        #expect(f2 == "mulaw")
        #expect(r2 == 8_000)
        guard case .mark(let name)? = CallInbound.parse(#"{"type":"mark","name":"m1"}"#) else { Issue.record("mark"); return }
        #expect(name as? String == "m1")
        guard case .ignored? = CallInbound.parse(#"{"type":"mark","name":""}"#) else { Issue.record("nameless mark"); return }
        guard case .clear? = CallInbound.parse(#"{"type":"interruption"}"#) else { Issue.record("interruption"); return }
        guard case .clear? = CallInbound.parse(#"{"type":"clear"}"#) else { Issue.record("clear"); return }
        guard case let .transcript(t, final)? = CallInbound.parse(#"{"type":"interim_transcript_received","data":"hel"}"#) else {
            Issue.record("interim"); return
        }
        #expect(t == "hel")
        #expect(!final)
        guard case let .appAction(id, action, args)? =
            CallInbound.parse(#"{"type":"app_action","action":{"action_id":"x1","name":"open_screen","arguments":{"to":"cart"}}}"#) else {
            Issue.record("app_action"); return
        }
        #expect(id == "x1")
        #expect(action == "open_screen")
        #expect(args["to"] as? String == "cart")
        for ignored in [#"{"type":"widget","widget":{}}"#, #"{"type":"widget_pending"}"#, #"{"type":"pong"}"#, #"{"type":"ack"}"#, #"{"type":"new_thing"}"#] {
            guard case .ignored? = CallInbound.parse(ignored) else { Issue.record("\(ignored)"); return }
        }
        #expect(CallInbound.parse("not json") == nil)
    }
}
